101	    /**
102	     * The surplus is spent by the mine that grows what the account is short of, before the persona's
103	     * ship habit: the more one resource towers over the least, the more a build is the answer. The
104	     * floor ignores mild imbalance, so a safety action (a fleetsave under a visible raid) is never
105	     * outranked by an ordinary surplus; only a severe one — one resource hundreds of times another —
106	     * makes the mine the answer.
107	     */
108	    private function buildScarcityBoost(PerceptionSnapshot $perception, float $resourceNeed): float
109	    {
110	        if ($resourceNeed < 1.0) {
111	            return 0.0;
112	        }
113	
114	        $metal = 0.0;
115	        $crystal = 0.0;
116	        $deuterium = 0.0;
117	
118	        foreach ($perception->planets as $planet) {
119	            $metal += (float) ($planet['resources']['metal'] ?? 0.0);
120	            $crystal += (float) ($planet['resources']['crystal'] ?? 0.0);
121	            $deuterium += (float) ($planet['resources']['deuterium'] ?? 0.0);
122	        }
123	
124	        $abundant = max($metal, $crystal, $deuterium);
125	        $scarce = min($metal, $crystal, $deuterium);
126	
127	        // 0 below 10:1, 1.0 once one resource is 1,000x another: the scarce resource
128	        // ranks above the persona's habit only when it really is the binding constraint.
129	        return min(1.0, max(0.0, (log10($abundant / max(1.0, $scarce)) - 1.0) / 2.0));
130	    }
