559	    /**
560	     * The second half of a login (architecture step 5): the probes the login sent have reported, so the
561	     * account reads the fresh reports and writes a raid for each one its planner approves, up to the
562	     * archetype's waves and the free fleet slots. The raids are ordinary Raid work, due now.
563	     *
564	     * @return array{0: AiActionResult|null, 1: array<string, mixed>, 2: int}
565	     */
566	    private function raidWave(AiWorkItem $workItem, int $planetId): array
567	    {
568	        $profile = AiProfile::query()->where('player_id', $workItem->player_id)->where('enabled', true)->first();
569	        if ($profile === null) {
570	            return [null, [], 0];
571	        }
572	
573	        $since = (int) ($workItem->payload['since'] ?? 0);
574	        $reportIds = \OGame\Models\Message::query()
575	            ->where('user_id', $workItem->player_id)
576	            ->whereNotNull('espionage_report_id')
577	            ->where('created_at', '>=', \Carbon\Carbon::createFromTimestamp(max(0, $since - 60)))
578	            ->orderByDesc('id')
579	            ->pluck('espionage_report_id');
580	
581	        $doctrine = app(ManagerDoctrine::class);
582	        $phase = app(GamePhaseMachine::class)->of(app(PlayerServiceFactory::class)->make($workItem->player_id));
583	        $limit = min(
584	            $doctrine->int($profile->archetype, 'raid_waves', $phase),
585	            app(FleetSlots::class)->free($workItem->player_id) - $doctrine->int($profile->archetype, 'keep_slots_free', $phase),
586	        );
587	        $claims = app(LoginReservations::class);
588	        $claims->reset();
589	        $placed = 0;
590	
591	        try {
592	            foreach ($reportIds->unique() as $reportId) {
593	                if ($placed >= $limit) {
594	                    break;
595	                }
596	
597	                $plan = app(RaidPlanner::class)->plan($workItem->player_id, (int) $reportId);
598	                if (!$plan instanceof QueueableRaid) {
599	                    continue;
600	                }
601	
602	                AiWorkItem::query()->firstOrCreate(
603	                    ['idempotency_key' => 'intent:wave:' . $workItem->id . ':' . $reportId],
604	                    [
605	                        'player_id' => $workItem->player_id,
606	                        'kind' => AiWorkKind::Raid,
607	                        'due_at' => now(),
608	                        'schedule_generation' => (int) ($workItem->schedule_generation ?? 1),
609	                        'state' => AiWorkState::Pending,
610	                        'payload' => [
611	                            self::PAYLOAD_PLANET_ID => $plan->originPlanetId,
612	                            self::PAYLOAD_TARGET_GALAXY => $plan->targetGalaxy,
613	                            self::PAYLOAD_TARGET_SYSTEM => $plan->targetSystem,
614	                            self::PAYLOAD_TARGET_POSITION => $plan->targetPosition,
615	                            self::PAYLOAD_TARGET_TYPE => $plan->targetType,
616	                            self::PAYLOAD_MISSION_TYPE => $plan->missionType,
617	                            self::PAYLOAD_LAUNCH_UNITS => $plan->launchUnits,
618	                            self::PAYLOAD_REASON => 'raid_wave:' . $reportId,
619	                        ],
620	                    ],
621	                );
622	                $claims->claim($plan->originPlanetId, $plan->launchUnits);
623	                $placed++;
624	            }
625	        } finally {
626	            $claims->reset();
627	        }
628	
629	        return [AiActionResult::succeeded(AiQueueActionReason::RaidWavePlanned), ['raids' => $placed], $planetId];
630	    }
