667	     * @return array{0: AiActionResult|null, 1: array<string, mixed>, 2: int}
668	     */
669	    private function defend(AiWorkItem $workItem, int $planetId): array
670	    {
671	        $step = $this->fromPayload(QueueableDefend::class, [
672	            'sourcePlanetId' => $workItem->payload[self::PAYLOAD_SOURCE_PLANET_ID] ?? null,
673	            'targetPlanetId' => $workItem->payload[self::PAYLOAD_TARGET_PLANET_ID] ?? null,
674	        ]) ?? app(QueueableDefendPlanner::class)->plan($workItem->player_id);
675	
676	        if (!$step instanceof QueueableDefend) {
677	            return [null, [], 0];
678	        }
679	
680	        return [
681	            app(QueueAiDefend::class)->handle($workItem->player_id, $step->sourcePlanetId, $step->targetPlanetId),
682	            ['source_planet_id' => $step->sourcePlanetId, 'target_planet_id' => $step->targetPlanetId],
683	            $step->sourcePlanetId,
684	        ];
685	    }
686	
687	    /**
688	     * The next building the account's economy plan says to queue, only when it is
689	     * actually a building (the same plan answers with research when that is next).
690	     */
691	    private function plannedBuild(int $playerId): ?QueueableBuilding
692	    {
693	        $plan = app(QueueableBuildingPlanner::class)->plan($playerId);
694	
695	        return $plan instanceof QueueableBuilding ? $plan : null;
696	    }
697	
698	    /**
699	     * The next technology the economy plan says to research, only when it is one.
700	     */
701	    private function plannedResearch(int $playerId): ?QueueableResearch
702	    {
703	        $plan = app(QueueableBuildingPlanner::class)->plan($playerId);
704	
705	        return $plan instanceof QueueableResearch ? $plan : null;
706	    }
707	
708	    private function reason(AiWorkItem $workItem): string
709	    {
710	        return (string) ($workItem->payload[self::PAYLOAD_REASON] ?? 'scheduled');
711	    }
712	
713	    /**
714	     * Builds a step from payload fields, or null when any named field is absent.
715	     * Absence means an older work item that never carried the binding, which the
716	     * caller then re-plans or drops.
717	     *
718	     * @param class-string $class
719	     * @param array<string, mixed> $fields
720	     */
721	    private function fromPayload(string $class, array $fields): object|null
722	    {
723	        foreach ($fields as $field) {
724	            if ($field === null) {
725	                return null;
726	            }
727	        }
728	
729	        return app()->makeWith($class, $fields);
730	    }
731	}

