 25	/**
 26	 * Module-owned adapter over the host's expedition mission.
 27	 *
 28	 * The slot-16 coordinate, the slot budget and the outcome table are the host's;
 29	 * the module adds the never-fleetsave refusal (EXP-001): a single small
 30	 * disposable hull, never the fleet the account depends on.
 31	 */
 32	class QueueAiExpeditionAction implements QueueAiExpedition
 33	{
 34	    /** The cheapest speed the host accepts (10%), the classic expedition cruise. */
 35	    public const EXPEDITION_SPEED = 1.0;
 36	
 37	    /** The shortest expedition, the classic hourly cadence. */
 38	    public const EXPEDITION_HOLDING_HOURS = 1;
 39	
 40	    public function __construct(
 41	        private PlayerGameStateService $playerGameStateService,
 42	        private PlanetServiceFactory $planetServiceFactory,
 43	    ) {
 44	    }
 45	
 46	    public function handle(int $playerId, int $planetId, int $galaxy, int $system): AiActionResult
 47	    {
 48	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
 49	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
 50	        }
 51	
 52	        try {
 53	            $player = $this->playerGameStateService->advance($playerId, $planetId);
 54	
 55	            if ($player->isBanned()) {
 56	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
 57	            }
 58	            if ($player->isInVacationMode()) {
 59	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
 60	            }
 61	
 62	            // A decision taken before the gate refused the account's own dispatch orders is not a second
 63	            // offer: the planner already reads that refusal as the account's lane and stops planning, and
 64	            // a decision it made earlier still sits queued here. Answering from the same memory the planner
 65	            // reads means the host is never asked a question the account has already been answered — which
 66	            // is what kept one body writing the host's own sentence five times in six hours.
 67	            if (app(RecentRefusals::class)->accountLane($playerId)) {
 68	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 69	            }
 70	
 71	            // The host refuses a dispatch when the account is already out of expedition slots ("You are
 72	            // conducting too many expeditions at the same time"), and the slot is the account's, shared by
 73	            // every body: a decision that was legal when the login made it stops being legal once another
 74	            // fleet takes the slot, which is what the decision-to-dispatch lag does to this lane. The
 75	            // host's own question is asked here, where the count is live, so the game never has to refuse.
 76	            if ($player->getExpeditionSlotsInUse() >= $player->getExpeditionSlotsMax()) {
 77	                return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 78	            }
 79	
 80	            $origin = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
 81	            $fleet = $this->disposableFleet($player, $origin);
 82	            if ($fleet === null) {
 83	                return AiActionResult::rejected(AiQueueActionReason::NoDisposableFleet);
 84	            }
 85	
 86	            $fleetMissions = app()->makeWith(FleetMissionService::class, ['player' => $player]);
 87	            $destination = new Coordinate($galaxy, $system, 16);
 88	
 89	            // The host refuses a flight whose fuel exceeds the planet's deuterium or the fleet's own
 90	            // tanks. A player sends the cargo hull alone before sending nothing, so the strongest
 91	            // hulls drop out of an expedition the full fleet cannot fuel.
 92	            if (!$this->canFuel($player, $origin, $fleet, $destination, $fleetMissions)) {
 93	                $fleet = $this->cargoOnly($player, $origin);
 94	                if ($fleet === null || !$this->canFuel($player, $origin, $fleet, $destination, $fleetMissions)) {
 95	                    return AiActionResult::rejected(AiQueueActionReason::SourceShortAtDispatch);
 96	                }
 97	            }
 98	
 99	            $mission = $fleetMissions->createNewFromPlanet(
100	                $origin,
101	                $destination,
102	                PlanetType::Planet,
103	                ExpeditionMission::getTypeId(),
104	                $fleet,
105	                new Resources(),
106	                self::EXPEDITION_SPEED,
107	                self::EXPEDITION_HOLDING_HOURS,
108	            );
109	
110	            return AiActionResult::queued($mission->id);
111	        } catch (Exception $exception) {
112	            return AiActionResult::rejected($exception->getMessage());
113	        }
114	    }
115	
116	    private function canFuel(PlayerService $player, PlanetService $origin, UnitCollection $fleet, Coordinate $destination, FleetMissionService $fleetMissions): bool
117	    {
118	        $fuel = (float) $fleetMissions->calculateConsumption($origin, $fleet, $destination, self::EXPEDITION_HOLDING_HOURS, self::EXPEDITION_SPEED);
119	
120	        return $fuel <= floor($origin->deuterium()->get()) && $fuel <= $fleet->getTotalFuelCapacity($player);
121	    }
122	
123	    private function cargoOnly(PlayerService $player, PlanetService $origin): ?UnitCollection
124	    {
125	        $cargo = app(QueueableExpeditionPlanner::class)->disposableShip($player, $origin);
126	        if ($cargo === null) {
127	            return null;
128	        }
129	
130	        $fleet = new UnitCollection();
131	        $fleet->addUnit($cargo, 1);
132	
133	        return $fleet;
134	    }
135	
136	    /**
137	     * The expedition fleet: one of each role the body owns — the strongest combat
138	     * hull (survive a pirate), the fastest civil hull (pathfinder), the smallest
139	     * cargo (carry the find) and a probe — never the whole stock (EXP-002). Roles
140	     * the body does not own are simply absent, and each hull flies once.
141	     */
142	    private function disposableFleet(PlayerService $player, PlanetService $origin): ?UnitCollection
143	    {
144	        $planner = app(QueueableExpeditionPlanner::class);
145	
146	        $cargo = $planner->disposableShip($player, $origin);
147	        if ($cargo === null) {
148	            return null;
149	        }
150	
151	        $hulls = [$cargo->machine_name => $cargo];
152	
153	        foreach ([$planner->combatHull($player, $origin), $planner->fastestCivilHull($player, $origin)] as $ship) {
154	            if ($ship !== null) {
155	                $hulls[$ship->machine_name] = $ship;
156	            }
157	        }
158	
159	        $probe = ObjectService::getUnitObjectByMachineName(EspionageMission::getRequiredShipMachineNames()[0]);
160	        if ($origin->getShipUnits()->getAmountByMachineName($probe->machine_name) > 0) {
161	            $hulls[$probe->machine_name] = $probe;
162	        }
163	
164	        $fleet = new UnitCollection();
165	        foreach ($hulls as $ship) {
166	            $fleet->addUnit($ship, 1);
167	        }
168	
169	        return $fleet;
170	    }
171	}

