    /**
     * Whether the account already holds a refusal of a dispatch from this body, or to this target.
     *
     * A planner reads this memory before it decides, but an intent is a decision already made: the worker
     * may run it hours later, and a refusal raised in between is one no planner could have read. Asking
     * the gate again for that body or target is the same answer twice, so the memory answers the intent
     * the way it answers a planner.
     */
    public function cools(int $playerId, int $planetId, int $galaxy, int $system, int $position): bool
    {
        foreach ($this->recent($playerId) as $receipt) {
            $decision = $receipt->result['decision'] ?? [];

            if ($galaxy > 0
                && (int) ($decision['target_galaxy'] ?? 0) === $galaxy
                && (int) ($decision['target_system'] ?? 0) === $system
                && (int) ($decision['target_position'] ?? 0) === $position) {
                return true;
            }

            if ($planetId > 0 && ! $this->targetSide($receipt) && (int) ($receipt->result['planet_id'] ?? 0) === $planetId) {
                return true;
            }
        }

        return false;
    }
